    SELECT x AS k, COALESCE(x, 0) AS coalv FROM c108_a
    UNION ALL
    SELECT y AS k, COALESCE(y, 0) AS coalv FROM c108_b
    UNION ALL
    SELECT z AS k, COALESCE(z, 0) AS coalv FROM c108_c
) u ON t.x = u.k
